596			if ($MyRow[0] != $NewValue) {
597				$SQL = "UPDATE " . $Table . " SET " . $Field . "='" . $NewValue . "' WHERE " . $Criteria;
598				$Response = executeSQL($SQL, false);
599				if ($Response == 0) {
600					OutputResult(__('The field') . ' ' . $Field . ' ' . __('has been updated'), 'success');
601				} else {
602					OutputResult(__('The field') . ' ' . $Field . ' ' . __('could not be updated') . '<br />' . $SQL, 'error');
603				}
604			} else {
605				OutputResult(__('The field') . ' ' . $Field . ' ' . __('is already correct'), 'info');
606			}
607		} elseif (isset($SQLFile)) {
608			$Response = executeSQL("UPDATE " . $Table . " SET " . $Field . "='" . $NewValue . "' WHERE " . $Criteria, false);
609		}
610	}
611	
612	function DeleteRecords($Table, $Criteria) {
613		$SQL = "SELECT * FROM " . $Table . " WHERE " . $Criteria;
614		$Result = DB_query($SQL);
615		if (DB_num_rows($Result) > 0) {
616			$Response = executeSQL("DELETE FROM " . $Table . " WHERE " . $Criteria, false);
617			if ($Response == 0) {
618				OutputResult(__('Rows have been deleted from') . ' ' . $Table, 'success');
619			} else {
620				OutputResult(__('Rows could not be deleted from') . ' ' . $Table, 'error');
621			}
622		} else {
623			OutputResult(__('There was nothing to delete from') . ' ' . $Table, 'info');
624		}
625	}
626	
627	function DropTable($Table) {
628		$SQL = "SHOW tables WHERE Tables_in_" . $_SESSION['DatabaseName'] . " ='" . $Table . "'";
629		$Result = DB_query($SQL);
630		if (DB_num_rows($Result) > 0) {
631			$Response = executeSQL("DROP TABLE IF EXISTS `" . $Table . "`");
632			if ($Response == 0) {
633				OutputResult(__('The old table') . ' ' . $Table . ' ' . __('has been removed'), 'success');
634			} else {
635				OutputResult(__('The old table') . ' ' . $Table . ' ' . __('could not be removed'), 'error');
636			}
637		} else {
638			OutputResult(__('The old table') . ' ' . $Table . ' ' . __('has already been removed'), 'info');
639		}
640	}
641	
642	function InsertRecord($Table, $CheckFields, $CheckValues, $Fields, $Values) {
643		if (DB_table_exists($Table)) {
644			$SQL = "SELECT * FROM " . $Table . " WHERE ";
645			$SizeOfCheckFields = sizeOf($CheckFields);
646			for ($i = 0;$i < $SizeOfCheckFields;$i++) {
647				$SQL = $SQL . $CheckFields[$i] . "='" . DB_escape_string($CheckValues[$i]) . "' AND ";
648			}
649			$SQL = mb_substr($SQL, 0, mb_strlen($SQL) - 5);
650			$Result = DB_query($SQL);
651		}
652		if (DB_num_rows($Result) == 0 or isset($SQLFile)) {
653			$SQL = "INSERT INTO " . $Table . " (";
654			$SizeOfFields = sizeOf($Fields);
655			for ($i = 0;$i < $SizeOfFields;$i++) {
656				$SQL = $SQL . $Fields[$i] . ",";
657			}
658			$SQL = mb_substr($SQL, 0, mb_strlen($SQL) - 1) . ") VALUES (";
659			$SizeOfValues = sizeOf($Values);
660			for ($i = 0;$i < $SizeOfValues;$i++) {
661				$SQL = $SQL . "'" . DB_escape_string($Values[$i]) . "',";
662			}
663			$SQL = mb_substr($SQL, 0, mb_strlen($SQL) - 1) . ")";
664			$Response = executeSQL($SQL);
665			if ($Response == 0) {
666				OutputResult(__('The record has been inserted'), 'success');
667			} else {
668				OutputResult(__('The record could not be inserted') . ' ' . __('The sql used was') . '<br />' . $SQL, 'error');
669			}
670		} else {
671			OutputResult(__('The record is already in the table'), 'info');
672		}
673	}
674	
675	function DropPrimaryKey($Table, $OldKey) {
676		$SQL = "SELECT COLUMN_NAME, TABLE_NAME FROM information_schema.key_column_usage WHERE table_name='" . $Table . "' AND constraint_name='primary' AND table_schema='" . $_SESSION['DatabaseName'] . "'";
677		$Result = DB_query($SQL);
678		$Total = DB_num_rows($Result);
679		$Fields = array();
680		while ($MyRow = DB_fetch_array($Result)) {
681			$Fields[] = $MyRow['COLUMN_NAME'];
682		}
683		if ($Total == sizeOf($OldKey) and $Fields == $OldKey) {
684			$SQL = "ALTER TABLE `" . $Table . "` DROP PRIMARY KEY";
685			$Response = executeSQL($SQL);
686			if ($Response == 0) {
687				OutputResult(__('The primary key in') . ' ' . $Table . ' ' . __('has been removed'), 'success');
688			} else {
689				OutputResult(__('The primary key in') . ' ' . $Table . ' ' . __('could not be removed') . '<br />' . $SQL, 'error');
690			}
691		} else {
692			OutputResult(__('The primary key in') . ' ' . $Table . ' ' . __('has already been removed'), 'info');
693		}
694	}
695	
696	function AddPrimaryKey($Table, $Fields) {
697		$SQL = "SELECT table_name FROM information_schema.key_column_usage WHERE table_name='" . $Table . "' AND constraint_name='primary' AND
698			table_schema='" . $_SESSION['DatabaseName'] . "'";
699		$Result = DB_query($SQL);
700		if (DB_num_rows($Result) != sizeOf($Fields)) {
701			$KeyString = implode(",", $Fields);
702			$Response = executeSQL("ALTER TABLE `" . $Table . "` ADD PRIMARY KEY ( " . $KeyString . " )");
703			if ($Response == 0) {
704				OutputResult(__('The primary key in') . ' ' . $Table . ' ' . __('has been added'), 'success');
705			} else {
706				OutputResult(__('The primary key in') . ' ' . $Table . ' ' . __('could not be added') . '<br />' . "ALTER TABLE " . $Table . " ADD PRIMARY KEY ( " . $KeyString . " )", 'error');
707			}
708		} else {
709			OutputResult(__('The primary key in') . ' ' . $Table . ' ' . __('has already been added'), 'info');
710		}
711	}
712	
713	function RenameTable($OldName, $NewName) {
714		$Newsql = "SHOW TABLES WHERE Tables_in_" . $_SESSION['DatabaseName'] . "='" . $NewName . "'";
715		$Newresult = DB_query($Newsql);
716		$Oldsql = "SHOW TABLES WHERE Tables_in_" . $_SESSION['DatabaseName'] . "='" . $OldName . "'";
717		$Oldresult = DB_query($Oldsql);
718	
719		if (DB_num_rows($Newresult) != 0 and DB_num_rows($Oldresult) != 0) {
720			$Response = executeSQL("DROP TABLE " . $OldName . "", false);
721		}
722		if (DB_num_rows($Newresult) == 0) {
723			$SQL = "RENAME TABLE " . $OldName . " to " . $NewName;
724			$Response = executeSQL($SQL, false);
725			if ($Response == 0) {
726				OutputResult(__('The table') . ' ' . $OldName . ' ' . __('has been renamed to') . ' ' . $NewName, 'success');
727			} else {
728				OutputResult(__('The table') . ' ' . $OldName . ' ' . __('could not be renamed to') . ' ' . $NewName . '<br />' . $SQL, 'error');
729			}
730		} else {
731			OutputResult(__('The table') . ' ' . $NewName . ' ' . __('already exists'), 'info');
732		}
733	}
734	
735	function SetAutoIncStart($Table, $Field, $StartNumber) {
736		$GetLargestSQL = "SELECT MAX(" . $Field . ") AS highest FROM " . $Table;
737		$GetLargestResult = DB_query($GetLargestSQL);
738		$LargestRow = DB_fetch_array($GetLargestResult);
739		if ($LargestRow['highest'] > $StartNumber) {
740			OutputResult(__('You are trying to set the auto increment number below the current number'), 'warn');
741		} else {
742			$Response = executeSQL("ALTER TABLE " . $Table . " AUTO_INCREMENT = " . $StartNumber, false);
743			OutputResult(__('The auto increment field in table') . ' ' . $Table . __('has been updated'), 'success');
744		}
745	}
746	
747	function OutputResult($Msg, $Status) {
748		if ($Status == 'error') {
749			$_SESSION['Updates']['Errors']++;
750			$_SESSION['Updates']['Messages'][] = $Msg;
751		} elseif ($Status == 'success') {
752			$_SESSION['Updates']['Successes']++;
753		} else {
754			$_SESSION['Updates']['Warnings']++;
755		}
756	}
