if (isset($_POST['submit'])) {

	//initialise no input errors assumed initially before we test
	$InputError = 0;
	$i=1;

	/* actions to take once the user has clicked the submit button
	ie the page has called itself with some user input */

	//first off validate inputs sensible

	$_POST['DebtorNo'] = mb_strtoupper($_POST['DebtorNo']);

	$CCOld = array('creditlimit' => 0, 'holdreason' => '');
	if (!isset($_POST['New'])) {
		$CCResult = DB_query("SELECT creditlimit, holdreason FROM debtorsmaster WHERE debtorno='" . $_POST['DebtorNo'] . "'");
		if (DB_num_rows($CCResult) == 1) {
			$CCOld = DB_fetch_array($CCResult);
		}
	}
	if (!$CCCanChange) {
		// whatever was posted (the fields are disabled so usually nothing was), the limit and the credit status are not theirs to change
		if (!isset($_POST['New'])) {
			$_POST['CreditLimit'] = locale_number_format($CCOld['creditlimit'], 2);
			$_POST['HoldReason'] = $CCOld['holdreason'];
		} else {
			$CCSettings = CreditControlSettings();
			$_POST['CreditLimit'] = locale_number_format($_SESSION['DefaultCreditLimit'], 2);
			if ($CCSettings['CreditControlNormalReason'] !== '') {
				$_POST['HoldReason'] = $CCSettings['CreditControlNormalReason'];
			} elseif (!isset($_POST['HoldReason'])) {
				$_POST['HoldReason'] = 0;
			}
		}
	}

	$SQL="SELECT COUNT(debtorno) FROM debtorsmaster WHERE debtorno='".$_POST['DebtorNo']."'";
	$Result = DB_query($SQL);
	$MyRow=DB_fetch_row($Result);
	if ($MyRow[0]>0 AND isset($_POST['New'])) {
		$InputError = 1;
		prnMsg( __('The customer number already exists in the database'),'error');
		$Errors[$i] = 'DebtorNo';
		$i++;
	} elseif (mb_strlen($_POST['CustName']) > 40 OR mb_strlen($_POST['CustName'])==0) {
		$InputError = 1;
		prnMsg( __('The customer name must be entered and be forty characters or less long'),'error');
		$Errors[$i] = 'CustName';
		$i++;
	} elseif ($_SESSION['AutoDebtorNo']==0 AND mb_strlen($_POST['DebtorNo']) ==0) {

